import{_ as r,l as n,o as e,c as i,v as l,p as s,x as t,d as A,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"索洛残差","description":"","frontmatter":{"title":"索洛残差","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/solow-residual.md","filePath":"econ/solow-residual.md","lastUpdated":1789023840000}'),E={name:"econ/solow-residual.md"};function h(c,a,_,u,m,B){const o=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=l('<h1 id="索洛残差" tabindex="-1">索洛残差 <a class="header-anchor" href="#索洛残差" aria-label="Permalink to &quot;索洛残差&quot;">​</a></h1><div class="epigraph"><p>把产出增长里不能由可测要素解释的部分叫技术变化，是会计；把它直接读成发明与研发，已经多走了一步。</p><footer>—— Solow, Technical Change and the Aggregate Production Function, REStat 1957</footer></div><p><a href="/econ/solow-growth">上一课</a>把 \\(Y=F(K,AL)\\) 的 \\(g=\\dot{A}/A\\) 当成外生参数，并声明索洛残差是核算、不是已经识别了研发部门。本课的缺口就是把那句核算写开：残差如何从账户里算出来，以及它为什么<strong>不是</strong>技术本身。黄金律下一课仍在外生 \\(g\\) 下选 \\(k\\)；内生增长再把 \\(A\\) 的来源打开。本课只钉残差的身份。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>索洛模型需要一条 \\(A\\) 的路径，数据里没有直接观测的「技术」。可观测的是实际产出、资本存量与劳动投入。若假定规模报酬不变、要素按边际产出付酬，则增长中被 \\(K\\) 与 \\(L\\) 解释掉的部分可以扣掉，剩下的叫全要素生产率（TFP）或索洛残差。缺口不是再写 \\(\\dot{k}=sf(k)-(n+g+\\delta)k\\)，而是：这个剩余包含什么，不能当成研发政策的充分统计量。</p><p><span class="marginnote">1957 的残差是时间序列上的 \\(\\Delta \\ln A\\)。截面上把穷国的落后写成同一个 \\(A\\)，是发展核算，公式同源、问题不同，更后的课再拆。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对数线性后，增长核算写</p> \\[\\Delta\\ln Y = \\alpha\\Delta\\ln K + (1-\\alpha)\\Delta\\ln L + \\Delta\\ln A, \\]<p>\\(\\alpha\\) 用收入法中的资本份额代理弹性。\\(\\Delta\\ln A\\) 是残差。劳动要先按质量或工时调整，否则教育与努力进入 \\(A\\)。资本要用实际存量，价格平减与利用率一错，\\(A\\) 跟着错——回到<a href="/econ/price-index-real">价格指数</a>与链式物量。</p>',10)),(e(),s(p,null,{default:t(()=>[d(o,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E5%AE%9E%E9%99%85%E4%BA%A7%E5%87%BA%E5%A2%9E%E9%95%BF%22%5D%20--%3E%20ACC%5B%22%E5%A2%9E%E9%95%BF%E6%A0%B8%E7%AE%97%22%5D%0A%20%20K%5B%22%E8%B5%84%E6%9C%AC%E8%B4%A1%E7%8C%AE%22%5D%20--%3E%20ACC%0A%20%20L%5B%22%E5%8A%B3%E5%8A%A8%E8%B4%A1%E7%8C%AE%22%5D%20--%3E%20ACC%0A%20%20ACC%20--%3E%20RES%5B%22%E6%AE%8B%E5%B7%AE%20%CE%94ln%20A%22%5D%0A%20%20RES%20--%3E%20NOT%5B%22%E4%B8%8D%E7%AD%89%E4%BA%8E%E5%B7%B2%E8%AF%86%E5%88%AB%E7%9A%84%E6%8A%80%E6%9C%AF%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>索洛模型里的 \\(g\\) 是这条残差的模型对应物。把残差当参数，模型才能关闭；把残差当「发明」，需要独立的研发、专利或品种数据。本课停在会计。</p><h3 id="份额与利用率" tabindex="-1">份额与利用率 <a class="header-anchor" href="#份额与利用率" aria-label="Permalink to &quot;份额与利用率&quot;">​</a></h3><p>\\(\\alpha\\) 不是常数：不完全竞争、测量误差、自我雇用的混合收入都会让份额漂。产能利用率顺周期时，衰退里 \\(K\\) 的贡献被高估、\\(A\\) 被低估（或反向，取决于是否调整利用率）。劳动窖藏同样把周期塞进残差。这些是对「\\(A\\)=技术」的直接警告。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>残差吸收一切模型没写进去的东西：技术、制度、误配置、质量调整、加总误差。Hicks 中性、劳动增进型只是把同一剩余塞进不同位置的 \\(F\\)。即便每家工厂技术不变，资源从高生产率企业转到低生产率企业，加总 \\(A\\) 也会掉——那是错配课的入口，本课先承认加总残差无法区分「不会做」与「配错了」。</p><p>周期中残差亲周期，并不证明技术冲击驱动了周期：利用率与窖藏足够编出同样的剩余。RBC 把残差当冲击，是理论选择；本课的会计不替那一课做决定。增长核算还可以把劳动质量（教育、经验）从 \\(L\\) 里提出来，残差会变小——那不是「技术变少了」，是把一块剩余改名为 \\(h\\)。链式物量与 hedonic 已经把一部分质量写进 \\(Y\\)，再从残差里读「发明」，会重复计算。</p><p>要素投入若用小时而非人数，\\(A\\) 的周期更干净一些，仍不是技术。开放经济里，贸易条件变动可以让实际收入与实际产出分叉，残差不要混用 GNI 与 GDP 物量。</p><p><span class="marginnote">规模报酬不变加欧拉定理，才用收入份额当产出弹性。有递增报酬或经济利润时，残差的「技术」解释更弱。内生增长正是要离开这个封闭。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把残差写成专利数，也不要把某一两年的 TFP 跳跃写成「改革成功」而不核对 \\(K\\)、\\(L\\) 与平减。本课不估计研发弹性。外汇 CIP 与资产价格不进生产函数；PPP 篮子进入截面比较，那是发展核算，不是本课的时间差分。量化栏的成交不是 \\(A\\)。</p><p>GDP 与 GNI 的物量不同，残差要声明用哪一个 \\(Y\\)。链式水平不可加时，产业 TFP 加总也不等于宏观残差，那是指数性质。黄金律下一课仍把 \\(g\\) 当外生参数；本课只禁止把参数 \\(g\\) 与核算残差偷偷画等号。</p><p>后课默认：谈到索洛的 \\(g\\) 或 TFP，先把它当残差，再决定要不要赋予技术含义。下一课问：外生 \\(s\\) 会不会把 \\(k\\) 推过黄金律。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>索洛模型把 \\(g\\) 当参数；1957 的残差是从 \\(Y\\)、\\(K\\)、\\(L\\) 里扣出来的会计。</li><li>\\(\\Delta\\ln A\\) 含技术，也含利用率、质量、错配与加总误差。</li><li>收入份额当弹性，依赖竞争与报酬不变。</li><li>残差不是研发部门，也不是周期技术冲击的证明。</li><li>把教育从 \\(L\\) 中提出来，只是给剩余改名，不是识别发明。</li><li>出处：Solow, REStat 1957；对照 1956 的模型。</li></ul>',14))])}const C=r(E,[["render",h]]);export{f as __pageData,C as default};
